import json,glob,collections
F=['input','output','cache_read','cache_write']
def z(): return {k:0 for k in F}|{'cost':0.0,'records':0,'runs':0,'reported':0,'no_usage':0,'mark_only':0,'no_output':0,'multi':0}
tot=collections.defaultdict(z); alt=collections.defaultdict(lambda:{k:0 for k in F})
for kind,label in [('history','tasks'),('asks','questions')]:
    for f in sorted(glob.glob(f'.suspense/{kind}/*.json')):
        r=json.load(open(f)); h='claude' if r.get('harness')=='claude' else 'not recorded'
        for key in [(label,h),(label,'*'),('*','*')]:
            tot[key]['records']+=1
        out=r.get('output') or []
        res=[l for l in out if isinstance(l,dict) and l.get('type')=='result']
        keys=[(label,h),(label,'*'),('*','*')]
        if not out:
            only_mark = not r.get('userPrompt') and not r.get('error') and not r.get('harness')
            for k in keys: tot[k]['mark_only' if only_mark else 'no_output']+=1
            continue
        for k in keys: tot[k]['runs']+=1
        withu=[l for l in res if l.get('modelUsage') or l.get('total_cost_usd') is not None or l.get('usage')]
        if not withu:
            for k in keys: tot[k]['no_usage']+=1
            continue
        last=withu[-1]; mu=last.get('modelUsage') or {}
        s={'input':sum(m.get('inputTokens',0) for m in mu.values()),
           'output':sum(m.get('outputTokens',0) for m in mu.values()),
           'cache_read':sum(m.get('cacheReadInputTokens',0) for m in mu.values()),
           'cache_write':sum(m.get('cacheCreationInputTokens',0) for m in mu.values())}
        assert mu, f
        cost=last.get('total_cost_usd') or 0.0
        for k in keys:
            tot[k]['reported']+=1; tot[k]['multi']+= len(withu)>1
            for x in F: tot[k][x]+=s[x]
            tot[k]['cost']+=cost
            for l in withu:
                u=l.get('usage') or {}
                for x,y in zip(F,['input_tokens','output_tokens','cache_read_input_tokens','cache_creation_input_tokens']): alt[k][x]+=u.get(y,0)
for k in [('tasks','claude'),('tasks','not recorded'),('tasks','*'),('questions','claude'),('questions','not recorded'),('questions','*'),('*','*')]:
    t=tot[k]; print(k, {x:(round(v,4) if isinstance(v,float) else v) for x,v in t.items()}); print('   usage-field sum:',alt[k])
EOF

