    runs.append(dict(t=int(f.split('/')[-1][:10]),label=label,h=h,sess=res[-1].get('session_id'),cost=res[-1].get('total_cost_usd') or 0.0,u=u))
runs.sort(key=lambda r:r['t'])
prev={}; mono=nonmono=0
