F=['input_tokens','output_tokens','cache_read_input_tokens','cache_creation_input_tokens']
runs=[]
for kind,label in [('history','tasks'),('asks','questions')]:
  for f in sorted(glob.glob(f'.suspense/{kind}/*.json')):
    r=json.load(open(f)); out=r.get('output') or []
    res=[l for l in out if isinstance(l,dict) and l.get('type')=='result']
    if not res: continue
    h='claude' if r.get('harness')=='claude' else 'not recorded'
    u={x:sum((l.get('usage') or {}).get(x,0) for l in res) for x in F}
    if len(res)>1: print('multi-result run',f.split('/')[-1][:10],[ (l.get('usage') or {}).get('output_tokens') for l in res],[round(l.get('total_cost_usd') or 0,2) for l in res])
    runs.append(dict(t=int(f.split('/')[-1][:10]),label=label,h=h,sess=res[-1].get('session_id'),cost=res[-1].get('total_cost_usd') or 0.0,u=u))
runs.sort(key=lambda r:r['t'])
prev={}; mono=nonmono=0
for r in runs:
    p=prev.get(r['sess'])
    if p is not None and r['cost']>=p-1e-9: r['delta']=r['cost']-p; mono+=1
    else:
        r['delta']=r['cost']
        if p is not None: nonmono+=1
    prev[r['sess']]=r['cost']
print('later runs in a conversation whose cost rose',mono,'fell',nonmono)
agg=collections.defaultdict(lambda:collections.Counter())
for r in runs:
    for k in [(r['label'],r['h']),(r['label'],'*'),('*','*')]:
        a=agg[k]; a['runs']+=1; a['naive']+=r['cost']; a['dedup']+=r['delta']
        for x in F: a[x]+=r['u'][x]
for k,a in sorted(agg.items()): print(k,{x:(round(v,2) if isinstance(v,float) else v) for x,v in a.items()})
